from collections import OrderedDict
cache = OrderedDict()
def get(k):
    if k in cache: cache.move_to_end(k); return cache[k]
    return None
def put(k, v, cap=3):
    cache[k] = v; cache.move_to_end(k)
    if len(cache) > cap: cache.popitem(last=False)
for k in ["a", "b", "c", "a", "d"]:
    put(k, k.upper())
print("cache holds:", list(cache))

