from collections import Counter
freq, store, CAP = Counter(), {}, 3
def put(k, v):
    store[k] = v; freq[k] += 1
    if len(store) > CAP:
        cold = min(store, key=lambda k: freq[k])
        del store[cold]
for k in ["a", "a", "b", "c", "d", "a"]:
    put(k, k.upper())
print("cache holds:", sorted(store))

